// ============================================================================
// Brand asset — the official Certify.cx mark
// ============================================================================
// The client's instruction (Jul): "Above is to be used through all. Including
// Invoice & Receipts & Emails & any other communication tool (Internal &
// External)." This module is the single server-side source of that mark.
//
// WHY THE LOGO IS INLINED AS BASE64 (and not read from disk):
// Vercel serverless functions only bundle files the tracer can see statically.
// A runtime `readFileSync(...)` against `public/` or `src/assets/` resolves
// relative to the lambda's own working directory and is NOT reliably included
// in the bundle — it works locally and 404s in production. Inlining the bytes
// as a module constant makes the asset part of the function bundle by
// construction. The ~93KB PNG becomes ~124KB of base64 here; that size is
// DELIBERATE, not an accident or a stray paste. Regenerate it (rather than
// hand-editing) whenever the client sends new artwork:
//
//   node -e "const f=require('fs');const b=f.readFileSync('src/assets/brand-mark.png').toString('base64');console.log(b.length)"
//
// Source of truth for the artwork: src/assets/brand-mark.png
// (352 x 339, 8-bit RGBA with transparency — teal outlined "C" enclosing a
// checkmark). The identical file is served publicly at public/brand-mark.png.
//
// Consumers:
//   api/_billing.js        -> embedPng() in the invoice / receipt PDF header
//   api/_emailTemplates.js -> BRAND_MARK_URL in the transactional email header
// ============================================================================

// One flat accent for every white surface we render on — the PDF documents and
// the HTML emails. This is the LIGHT-THEME accent from src/index.css
// (--color-accent: #0e9f6e), chosen because invoices, receipts and email cards
// are all white-background surfaces where the darker light-theme green keeps
// contrast legible. It replaces three near-but-unequal greens that had drifted
// apart: #0DA673 (PDF), #0da678 (billing email) and #3ECF8E (the dark-theme
// accent, which is too light to read on white).
export const BRAND_ACCENT_HEX = '#0e9f6e';

// Same colour as pdf-lib `rgb()` components (0-1 floats), so the PDF and the
// email cannot drift apart again: 0x0e/255, 0x9f/255, 0x6e/255.
export const BRAND_ACCENT_RGB = Object.freeze({
  r: 0x0e / 255,
  g: 0x9f / 255,
  b: 0x6e / 255,
});

// Public URL of the same mark, for HTML emails. Email clients will not render
// `cid:` or data-URI images reliably (Gmail web strips data URIs outright), so
// a plain hosted https PNG is the only treatment that works everywhere.
//
// This is DELIBERATELY not derived from APP_PUBLIC_URL any more (8 Aug). That
// var names whatever host the app is deployed behind and was set to
// https://app.certify.cx — a hostname that does not resolve — so every
// transactional email rendered a broken-image icon where the logo belongs, the
// registration alert the client screenshotted included. The mark lives on the
// public site and is not tied to the app host, so it gets its own var with a
// verified default; set BRAND_MARK_URL only if the artwork ever moves.
export const BRAND_MARK_URL = process.env.BRAND_MARK_URL
  || 'https://certify.cx/brand-mark.png';

// Raw PNG bytes for pdf-lib's `embedPng()`. Returns a fresh Buffer per call;
// pdf-lib copies what it needs, so callers never share mutable state.
export function brandMarkBytes() {
  return Buffer.from(BRAND_MARK_PNG_BASE64, 'base64');
}

// Intrinsic pixel dimensions of the artwork. Callers that scale the mark should
// use this ratio rather than assuming it is square — it is not (352 x 339).
export const BRAND_MARK_ASPECT = 352 / 339;

